/*
 * A080066  First differences of A000966 (number of zeros that n! will never
 *          end in).
 * https://oeis.org/A080066
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) = A000966(n+1) - A000966(n)
 * Range:     u8 n <= 85, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The OEIS sequence A000966 is generated by
   A000966(1) = 5;
   for k ≥ 1:
       A000966(k+1) = A000966(k) + (1 if k is in {A000966(1),…,A000966(k)} else 6)
   The difference between successive terms of A000966 is therefore 1 or 6,
   and a(n) equals this difference.  We generate the sequence only as far
   as required and cache it in static storage so that repeated calls with
   arbitrary n are fast. */

#include <stdlib.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /*  static storage for generated A000966 values  */
    static seq_t *b          = NULL;   /* b[1..]  */
    static size_t b_cap      = 0;      /* capacity of b */
    static size_t b_size     = 0;      /* number of elements stored (>=1 after init) */

    /*  static storage for membership test  */
    static bool *pres          = NULL;   /* pres[0..]  */
    static size_t pres_cap     = 0;      /* capacity of pres */

    if (n == 0)   /* offset is 1: a(0) is undefined, return 0 as a safe default */
        return 0;

    idx_t target = n + 1;   /* need b[n] and b[n+1] */

    /* ---------- ensure capacity for b ---------- */
    if (b_cap < target + 2) {          /* leave space for index 0 and n+1 */
        size_t new_cap = b_cap ? b_cap * 2 : 16;
        while (new_cap < target + 2)
            new_cap <<= 1;
        b = (seq_t *)realloc(b, new_cap * sizeof(seq_t));
        b_cap = new_cap;
    }

    /* ---------- ensure capacity for pres ---------- */
    /* we only need a rough upper bound; it will grow on demand later */
    if (pres_cap < (size_t)(target * 2)) {
        size_t new_pres = pres_cap ? pres_cap * 2 : 64;
        while (new_pres < (size_t)(target * 2))
            new_pres <<= 1;
        pres = (bool *)realloc(pres, new_pres * sizeof(bool));
        for (size_t i = pres_cap; i < new_pres; ++i)
            pres[i] = false;
        pres_cap = new_pres;
    }

    /* ---------- initialise first term if needed ---------- */
    if (b_size == 0) {
        b[1] = 5;          /* A000966(1) */
        b_size = 1;

        /* ensure pres can store the value 5 */
        if (5 >= pres_cap) {
            size_t new_pres = pres_cap ? pres_cap * 2 : 64;
            while (new_pres <= 5)
                new_pres <<= 1;
            pres = (bool *)realloc(pres, new_pres * sizeof(bool));
            for (size_t i = pres_cap; i < new_pres; ++i)
                pres[i] = false;
            pres_cap = new_pres;
        }
        pres[5] = true;
    }

    /* ---------- generate terms up to target ---------- */
    while (b_size < target) {
        idx_t idx = b_size;               /* current last index */

        /* make sure pres has entry for idx */
        if ((size_t)idx >= pres_cap) {
            size_t new_pres = pres_cap ? pres_cap * 2 : 64;
            while (new_pres <= (size_t)idx)
                new_pres <<= 1;
            pres = (bool *)realloc(pres, new_pres * sizeof(bool));
            for (size_t i = pres_cap; i < new_pres; ++i)
                pres[i] = false;
            pres_cap = new_pres;
        }
        seq_t delta = pres[idx] ? 1 : 6;
        seq_t next_val = b[idx] + delta;

        /* ensure pres can store next_val */
        size_t nval = (size_t)next_val;
        if (nval >= pres_cap) {
            size_t new_pres = pres_cap ? pres_cap * 2 : 64;
            while (new_pres <= nval)
                new_pres <<= 1;
            pres = (bool *)realloc(pres, new_pres * sizeof(bool));
            for (size_t i = pres_cap; i < new_pres; ++i)
                pres[i] = false;
            pres_cap = new_pres;
        }

        b_size++;
        b[b_size] = next_val;
        pres[nval] = true;
    }

    /* ---------- compute the requested difference ---------- */
    seq_t result = b[n + 1] - b[n];
    return result;
}
